import type * as Channel3Api from "../index.js";
/**
 * Search filters for the search API.
 */
export interface SearchFilters {
    /** If provided, only products from these brands will be returned */
    brand_ids?: string[] | null;
    gender?: Channel3Api.Gender | null;
    /** Offer conditions to match (OR). Defaults to ['new'], which also matches offers whose condition is unknown. Pass every value to disable condition filtering. */
    conditions?: Channel3Api.Condition[];
    /** Filter by age group. Age-agnostic products are treated as adult products. */
    age?: Channel3Api.Age[] | null;
    /** If provided, only products within this price range will be returned */
    price?: Channel3Api.SearchFilterPrice | null;
    /** Offer availability statuses to match (OR). Defaults to ['InStock']. An offer with no availability data counts as 'InStock'. Pass every value to disable availability filtering. */
    availability?: Channel3Api.OfferAvailabilityStatus[];
    /** If 'on_sale', only products with at least one on-sale offer (priced below its compare-at price) for the requested locale are returned. If omitted, no filter. */
    sale?: Channel3Api.Sale | null;
    /** If provided, only products from these websites will be returned. Accepts website IDs or domains (e.g. "nike.com"). */
    website_ids?: string[] | null;
    /** If provided, only products from these categories will be returned. Accepts category slugs. */
    category_ids?: string[] | null;
    /** If provided, products from these brands will be excluded from the results */
    exclude_brand_ids?: string[] | null;
    /** If provided, products from these websites will be excluded from the results. Accepts website IDs or domains (e.g. "nike.com"). */
    exclude_website_ids?: string[] | null;
    /** If provided, products in these categories (or their descendants) will be excluded from the results. Accepts category slugs. */
    exclude_category_ids?: string[] | null;
    /** [Beta: filter is experimental and may be changed] If provided, find products containing all of these colors. */
    colors?: Channel3Api.SearchColorsFilter | null;
    /** If provided, only products matching these key/value constraints will be returned. Keys are attribute handles (e.g. 'color', 'material') and values are lists of allowed values (OR within a key, AND across keys). When a category filter is also supplied, all keys must be valid attributes of at least one of the requested categories. See `Category.attributes` for the valid keys and values per category. */
    attributes?: Record<string, string[] | null> | null;
    /** If provided, only products with at least one offer whose physical dimensions satisfy every given range will be returned. Offer dimensions in responses are converted to the units used here. */
    dimensions?: Channel3Api.SearchFilterDimensions | null;
}
